func isInputDone() bool { return WsEofFlag == "Y" }

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseAmtField(s string) decimal.Decimal {
	// PIC 9(5)V99 : digits only, implied decimal
	// s length 7
	if len(s) == 0 {
		return decimal.NewFromInt(0)
	}
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.NewFromInt(0)
	}
	// keep only digits (COBOL numeric DISPLAY holds digits)
	// if any non-digit, treat as zero? assume digits
	n, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		// fallback: strip non-digits
		digits := ""
		for _, c := range t {
			if c >= '0' && c <= '9' {
				digits += string(c)
			}
		}
		if digits == "" {
			return decimal.NewFromInt(0)
		}
		n, _ = strconv.ParseInt(digits, 10, 64)
	}
	return decimal.New(n, -2)
}

func modCents(cents int64, mod int64) int64 {
	r := cents % mod
	if r < 0 {
		r += mod
	}
	return r
}

