		} else {
			c4 = ' '
		}
		c5 = byte('0' + d[4])
		// fix c3/c4 logic above: pos3 corresponds to d[2], pos4 to d[3]
		// already done
		_ = seen
	}
	var comma byte
	// comma is suppressed (space) if everything to its left is suppressed and everything between? i.e., if firstNZ == -1 or firstNZ > 1 (meaning d0,d1 zero)
	if firstNZ == -1 || firstNZ > 1 {
		comma = ' '
	} else {
		comma = ','
	}
	// handle negative: put minus? COBOL unsigned, ignore; but place '-' at leftmost? Not needed.
	out[0] = c0
	out[1] = c1
	out[2] = comma
	out[3] = c3
	out[4] = c4
	out[5] = c5
	out[6] = '.'
	out[7] = byte('0' + int(frac/10))
	out[8] = byte('0' + int(frac%10))
	s := string(out)
	if neg {
		// put minus sign in leftmost space if possible
		b := []byte(s)
		for i := len(b) - 1; i >= 0; i-- {
			if b[i] == ' ' {
				// find rightmost space before digit? Actually place at last space
			}
		}
		// simplest: replace last leading space with '-'
		idx := -1
		for i := 0; i < len(b); i++ {
			if b[i] == ' ' {
				idx = i
			} else {
				break
			}
			// stop at comma/point? spaces only at start
		}
		_ = idx
		// unsigned fields never negative here
	}
	return s
}

// format ZZ,ZZ9.9 (5 int digits, 1 frac digit)
func formatZZZZ9_9(v decimal.Decimal) string {
	t := v.Truncate(1)
	tenths := t.Shift(1).IntPart()
	var frac int64
	var intPart int64
	intMod := int64(100000)
	if tenths >= 0 {
		frac = tenths % 10
		intPart = (tenths / 10) % intMod
	} else {
		frac = -((-tenths) % 10)
		intPart = -((-tenths / 10) % intMod)
	}
	if intPart < 0 {
		intPart = -intPart
	}
	if frac < 0 {
		frac = -frac
	}
	d := make([]int, 5)
	tmp := intPart
	for i := 4; i >= 0; i-- {
		d[i] = int(tmp % 10)
		tmp /= 10
	}
	firstNZ := -1
	for i := 0; i < 5; i++ {
		if d[i] != 0 {
			firstNZ = i
			break
		}
	}
	var c0, c1, c3, c4, c5 byte
	if firstNZ == -1 {
		c0, c1, c3, c4 = ' ', ' ', ' ', ' '
		c5 = '0'
	} else {
		if 0 >= firstNZ {
			c0 = byte('0' + d[0])
		} else {
			c0 = ' '
		}
		if 1 >= firstNZ {
			c1 = byte('0' + d[1])
		} else {
			c1 = ' '
		}
		if 3 >= firstNZ {
			c3 = byte('0' + d[2])
		} else {
			c3 = ' '
		}
		if 4 >= firstNZ {
			c4 = byte('0' + d[3])
		} else {
			c4 = ' '
		}
		c5 = byte('0' + d[4])
	}
	var comma byte
	if firstNZ == -1 || firstNZ > 1 {
		comma = ' '
	} else {
		comma = ','
	}
	out := make([]byte, 8)
	out[0] = c0
	out[1] = c1
	out[2] = comma
	out[3] = c3
	out[4] = c4
	out[5] = c5
	out[6] = '.'
	out[7] = byte('0' + int(frac))
	return string(out)
}

func formatPIC99(v int64) string {
	m := ((v % 100) + 100) % 100
	return fmt.Sprintf("%02d", m)
}

func main() {
	// init decimals
	WsBigTotal = decimal.NewFromInt(0)
	WsWrapTotal = decimal.NewFromInt(0)
	WsSafeTotal = decimal.NewFromInt(0)
	WsHalf = decimal.NewFromInt(0)
	MainPara()
}

func MainPara() {
	// OPEN INPUT AMT-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file missing, treat as empty (COBOL would error, but exit non-zero)
		fmt.Fprintln(os.Stderr, err.Error())
		os.Exit(1)
	}
	sc := bufio.NewScanner(f)
	// allow long lines
	sc.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	inputLines = nil
	for sc.Scan() {
		line := sc.Text()
		// Scanner strips \n and \r; keep as is
		inputLines = append(inputLines, line)
	}
	f.Close()
	inputIdx = 0
	inputOpen = true
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	inputOpen = false
	SummaryPara()
}

func ReadPara() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	// pad to 11 with spaces
	if len(line) < 11 {
		line = line + strings.Repeat(" ", 11-len(line))
	} else if len(line) > 11 {
		line = line[:11]
	}
	acct := line[0:4]
	amtStr := line[4:11]
	curRec.ArAcct = acct
	curRec.ArAmt = parseAmtField(amtStr)
}

func ProcessPara() {
	// ADD AR-AMT TO WS-BIG-TOTAL
	sumBig := WsBigTotal.Add(curRec.ArAmt).Truncate(2)
	// store into 9(7)V99 : keep low-order digits
	centsBig := sumBig.Shift(2).IntPart()
	centsBig = modCents(centsBig, 1000000000)
	WsBigTotal = decimal.New(centsBig, -2)

	// MOVE WS-BIG-TOTAL TO WS-WRAP-TOTAL (drops high digits)
	centsWrap := WsBigTotal.Shift(2).IntPart()
	centsWrap = modCents(centsWrap, 10000000)
	WsWrapTotal = decimal.New(centsWrap, -2)

	// ADD AR-AMT TO WS-SAFE-TOTAL ON SIZE ERROR PERFORM OVERFLOW-PARA
	sumSafe := WsSafeTotal.Add(curRec.ArAmt).Truncate(2)
	limit := decimal.New(100000, 0)
	if sumSafe.GreaterThanOrEqual(limit) || sumSafe.LessThan(decimal.NewFromInt(0)) {
		OverflowPara()
	} else {
		// check fits in 9(5)V99 : already checked
		WsSafeTotal = sumSafe
	}

	// ADD 1 TO WS-COUNT
	WsCount = modCents(WsCount+1, 100)

	// COMPUTE WS-HALF = AR-AMT / 2 (truncated)
	two := decimal.NewFromInt(2)
	q := curRec.ArAmt.Div(two).Truncate(1)
	// store into 9(5)V9 : drop high digits if needed
	tenths := q.Shift(1).IntPart()
	tenths = modCents(tenths, 1000000)
	WsHalf = decimal.New(tenths, -1)

	// MOVEs to edited
	WsAmtEd = formatZZZZ9_99(curRec.ArAmt)
	WsWrapEd = formatZZZZ9_99(WsWrapTotal)
	WsSafeEd = formatZZZZ9_99(WsSafeTotal)
	WsHalfEd = formatZZZZ9_9(WsHalf)

	fmt.Printf("%s %s %s %s %s\n", curRec.ArAcct, WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)
	ReadPara()
}

func SummaryPara() {
	fmt.Printf("RECORDS: %s\n", formatPIC99(WsCount))
	fmt.Printf("OVERFLOWS: %s\n", formatPIC99(WsOverflows))
}

func OverflowPara() {
	WsOverflows = modCents(WsOverflows+1, 100)
}

var _ = padRight

